pub struct Stack<T> {
    items: Vec<T>,
}

impl<T> Stack<T> {
    pub fn new() -> Self {
        Stack { items: Vec::new() }
    }

    pub fn push(&mut self, item: T) {
        self.items.push(item);
    }

    pub fn pop(&mut self) -> Option<T> {
        if self.items.is_empty() {
            None
        } else {
            Some(self.items.remove(self.items.len() - 1))
        }
    }

    pub fn len(&self) -> usize {
        self.items.len()
    }

    pub fn is_empty(&self) -> bool {
        self.items.is_empty()
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn lifo_order() {
        let mut s = Stack::new();
        s.push(1);
        s.push(2);
        s.push(3);
        assert_eq!(s.pop(), Some(3));
        assert_eq!(s.pop(), Some(2));
        assert_eq!(s.pop(), Some(1));
        assert_eq!(s.pop(), None);
    }

    #[test]
    fn empty_pop() {
        let mut s: Stack<i32> = Stack::new();
        assert_eq!(s.pop(), None);
    }
}

#[derive(Debug, PartialEq, Eq)]
pub struct Version {
    pub major: u32,
    pub minor: u32,
    pub patch: u32,
}

pub fn parse_version(s: &str) -> Result<Version, String> {
    let parts: Vec<&str> = s.split('.').collect();
    if parts.len() != 3 {
        return Err(format!("expected 3 parts, got {}", parts.len()));
    }
    // Fix: indices are reversed
    let major: u32 = parts[0].parse().map_err(|e| format!("major: {}", e))?;
    let minor: u32 = parts[1].parse().map_err(|e| format!("minor: {}", e))?;
    let patch: u32 = parts[2].parse().map_err(|e| format!("patch: {}", e))?;
    Ok(Version { major, minor, patch })
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn parses_simple() {
        assert_eq!(
            parse_version("1.2.3").unwrap(),
            Version { major: 1, minor: 2, patch: 3 }
        );
    }

    #[test]
    fn parses_zeros() {
        assert_eq!(
            parse_version("0.0.0").unwrap(),
            Version { major: 0, minor: 0, patch: 0 }
        );
    }

    #[test]
    fn rejects_bad_input() {
        assert!(parse_version("1.2").is_err());
        assert!(parse_version("1.2.x").is_err());
    }
}

/// Returns the nth Fibonacci number (0-indexed).
pub fn fibonacci(n: u32) -> u64 {
    if n == 0 {
        return 0;
    }
    if n == 1 {
        return 1;
    }
    fibonacci(n - 1) + fibonacci(n - 2)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn it_computes_fib() {
        assert_eq!(fibonacci(0), 0);
        assert_eq!(fibonacci(1), 1);
        assert_eq!(fibonacci(2), 1);
        assert_eq!(fibonacci(7), 13);
        assert_eq!(fibonacci(10), 55);
    }
}

/// Counts the number of vowels (a, e, i, o, u — case-insensitive) in a string.
