/// Returns the mean of a slice. Should return None for empty slices.
pub fn mean(xs: &[f64]) -> Option<f64> {
    if xs.is_empty() {
        None
    } else {
        let sum: f64 = xs.iter().sum();
        sum / xs.len() as f64
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn it_means() {
        assert_eq!(mean(&[]), None);
        assert_eq!(mean(&[1.0, 2.0, 3.0]), Some(2.0));
        assert_eq!(mean(&[5.0]), Some(5.0));
        assert_eq!(mean(&[-1.0, 1.0]), Some(0.0));
    }
}

/// Returns true iff a and b are anagrams (same multiset of characters).
pub fn is_anagram(a: &str, b: &str) -> bool {
    if a.len() != b.len() {
        return false;
    }
    let ac: Vec<char> = a.chars().collect();
    let bc: Vec<char> = b.chars().collect();
    ac.sort();
    bc.sort();
    ac == bc
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn detects_anagrams() {
        assert!(is_anagram("listen", "silent"));
        assert!(is_anagram("a", "a"));
        assert!(is_anagram("", ""));
        assert!(!is_anagram("hello", "world"));
        assert!(!is_anagram("abc", "ab"));
    }
}

pub fn is_palindrome(s: &str) -> bool {
    let chars: Vec<char> = s.chars().collect();
    let n = chars.len();
    for i in 0..n / 2 {
        if chars[i] != chars[n - 1 - i] {
            return false;
        }
    }
    true
}

fn main() {
    println!("{}", is_palindrome("racecar"));
}

#[test]
fn test_is_palindrome() {
    assert!(is_palindrome(""), true);
    assert!(is_palindrome("a"), true);
    assert!(is_palindrome("racecar"), true);
    assert!(is_palindrome("hello"), false);
    assert!(is_palindrome("RaceCar"), false);
}

