use std::vec::Vec;

/// Merges two already-sorted ascending vectors into a single sorted vector.
/// Duplicates from both inputs are kept (so [1,2] + [2,3] -> [1,2,2,3]).
pub fn merge_sorted(a: &[i32], b: &[i32]) -> Vec<i32> {
    let mut out = Vec::with_capacity(a.len() + b.len());
    let (mut i, mut j) = (0, 0);
    while i < a.len() && j < b.len() {
        if a[i] <= b[j] {
            out.push(a[i]);
            i += 1;
        } else {
            out.push(b[j]);
            j += 1;
        }
    }
    out.extend_from_slice(&a[i..]);
    out.extend_from_slice(&b[j..]);
    out
}

fn main() {
    let m = merge_sorted(&[1, 4, 7], &[2, 3, 8]);
    println!("{:?}", m);
}

#[test]
fn test_merge_sorted() {
    assert_eq!(merge_sorted(&[], &[]), Vec::new());
    assert_eq!(merge_sorted(&[], &[1, 2]), vec![1, 2]);
    assert_eq!(merge_sorted(&[1, 2], &[3, 4]), vec![1, 2, 3, 4]);
    assert_eq!(merge_sorted(&[1, 2, 3], &[4, 5]), vec![1, 2, 3, 4, 5]);
    assert_eq!(merge_sorted(&[1, 2, 2], &[2, 3]), vec![1, 2, 2, 2, 3]);
}

use std::collections::HashMap;

/// Parses a string like "foo=bar, baz= qux " into a HashMap.
/// Whitespace around keys and values is trimmed.
/// Returns Err if any pair is missing `=`.
pub fn parse_kv(s: &str) -> Result<HashMap<String, String>, String> {
    let mut out = HashMap::new();
    if s.trim().is_empty() {
        return Ok(out);
    }
    for pair in s.split(',') {
        let pair = pair.trim();
        let (k, v) = pair.split_once('=').ok_or_else(|| format!("missing '=' in pair: {}", pair))?;
        out.insert(k.trim().to_string(), v.trim().to_string());
    }
    Ok(out)
}

fn main() {
    println!("{:?}", parse_kv("a=1, b=2"));
}

#[test]
fn test_parse_kv() {
    // Test normal case
    let result = parse_kv("a=1, b=2");
    assert_eq!(result, HashMap::from([("a", "1"), ("b", "2")]));

    // Test multiple comma-separated pairs
    let result = parse_kv("foo=bar, baz= qux");
    assert_eq!(result, HashMap::from([("foo", "bar"), ("baz", "qux")]));

    // Test empty input
    let result = parse_kv("");
    assert_eq!(result, HashMap::new());

    // Test malformed input lacking '='
    let result = parse_kv("foo, bar");
    assert_eq!(result, Err("missing '=' in pair: foo".to_string()));
}

/// Safely divides two integers; returns Err on division by zero.
pub fn safe_divide(a: i32, b: i32) -> Result<i32, String> {
    if b == 0 {
        Err("division by zero".to_string())
    } else {
        Ok(a / b)
    }
}

#[test]
fn test_safe_divide() {
    assert_eq!(safe_divide(10, 2), Ok(5));
    assert_eq!(safe_divide(10, 0), Err("division by zero".to_string()));
    assert_eq!(safe_divide(-5, 2), Ok(-2));
    assert_eq!(safe_divide(0, 3), Ok(0));
    assert_eq!(safe_divide(0, 0), Err("division by zero".to_string()));
}

fn main() {
    println!("{:?}", safe_divide(10, 2));
}

pub struct Stack<T> {
    items: Vec<T>,
}

impl<T> Stack<T> {
    pub fn new() -> Self { Stack { items: Vec::new() } }
    pub fn push(&mut self, x: T) { self.items.push(x); }
    pub fn pop(&mut self) -> Option<T> { self.items.pop() }
    pub fn peek(&self) -> Option<&T> { self.items.last() }
    pub fn len(&self) -> usize { self.items.len() }
    pub fn is_empty(&self) -> bool { self.items.is_empty() }
}

fn main() {
    let mut s: Stack<i32> = Stack::new();
    s.push(1);
    s.push(2);
    println!("top: {:?}, len: {}", s.peek(), s.len());
}

#[test]
fn test_push_pop_lifo() {
    let mut s = Stack::new();
    s.push(1);
    s.push(2);
    assert_eq!(s.peek(), Some(&2));
    assert_eq!(s.pop(), Some(2));
    assert_eq!(s.peek(), Some(&1));
    assert_eq!(s.pop(), Some(1));
    assert_eq!(s.peek(), None);
}

#[test]
fn test_pop_empty() {
    let mut s = Stack::new();
    assert_eq!(s.pop(), None);
}

