fn sum_strings(strs: Vec<&str>) -> i32 {
    let mut total = 0;
    for s in strs {
        match s.parse() {
            Ok(n) => total += n,
            Err(_) => {
                total = 0;
                break;
            }
        }
    }
    total
}

fn main() {
    let v = vec!["1", "2", "3", "oops", "4"];
    println!("{}", sum_strings(v));
}

